      if ((Get-FileHash -LiteralPath $fixturePath -Algorithm SHA256).Hash.ToLowerInvariant() -cne 'e2f13a8d2c22bfa5a788277700bf83796279d1639f7ef6838aff65c424b9ff74') { throw 'V5 재현 자료의 해시가 다릅니다. 실제 조회를 시작하지 않습니다.' }
      $fixture=Get-Content -LiteralPath $fixturePath -Raw -Encoding UTF8 | ConvertFrom-Json
      Assert-V7Check ($fixture.kind -eq 'cofiring_v5_first_read_fixture' -and @($fixture.samples).Count -eq 1441) 'real V5 first-tag fixture identity'
      $actual=[Array]::CreateInstance([object],[int[]]@(1441,3),[int[]]@(1,1))
      for ($r=0;$r -lt 1441;$r+=1) {
