        @{v=0.0;q='0';t=0;state='METADATA_PENDING'},
        @{v=0.0;q='0';t=46272.0;state='METADATA_PENDING'},
        @{v=0.0;q='Raw, Good';t=0;state='METADATA_PENDING'},
        @{v=0.0;q='Raw, Good';t=46272.0;state='VALUE'},
