        @{v='#NODATA';q='0';t=0;state='METADATA_PENDING'},
        @{v='#VALUE!';q='0';t=0;state='ERROR'},
        @{v='#NAME?';q='0';t=0;state='ERROR'},
        @{v=5;q='#N/A';t=0;state='ERROR'},
        @{v=-1;q='0';t=0;state='ERROR'},
        @{v=5;q='0';t=-1;state='ERROR'},
        @{v=5;q='-2146826246';t=0;state='ERROR'},
        @{v='unknown';q='0';t=0;state='ERROR'},
        @{v=5;q='0';t='broken-time';state='ERROR'},
        @{v=5;q='unknown';t=0;state='ERROR'}
