      $definitions=@(@{Row=0;Key='queried';Tag='a';Timestamp='t0'},@{Row=1;Key='not-queried';Tag='b';Timestamp='t1'})
      $partial=New-CofiringPartialSnapshot $oneBased $definitions $null 'Mock.PartialTag' @('queried')
      Assert-V7Check ($partial.capturedRows -eq 1 -and $partial.unqueriedRows -eq 1 -and $partial.samples[0].key -eq 'queried') 'unqueried TAGs are not exported as fake blank reads'

      # Actual V6 complete arrays and timing failure are fixtures ONLY, never live source.
      $v6Path=Join-Path $PSScriptRoot 'validation/v6-timing-fixture.json'
      if (-not [IO.File]::Exists($v6Path) -or (Get-FileHash -LiteralPath $v6Path -Algorithm SHA256).Hash.ToLowerInvariant() -cne '52017d520964e32058a5f77ee0c744ac6457c07e047b124ce0dc8ed13fd926fc') { throw 'V6 시간 재현 자료가 없거나 다릅니다. Excel은 시작하지 않습니다.' }
      $v6=Get-Content -LiteralPath $v6Path -Raw -Encoding UTF8 | ConvertFrom-Json
      Assert-V7Check ($v6.kind -eq 'cofiring_v6_timing_fixture' -and @($v6.samples).Count -eq 2882) 'actual V6 two complete 1441-row arrays'
      $second=$null
      foreach ($key in @('unit1CoalA1','unit1CoalA2')) {
        $tagRows=@($v6.samples | Where-Object { $_.key -eq $key })
        $observed=[Array]::CreateInstance([object],[int[]]@(1441,3),[int[]]@(1,1))
        for ($i=0;$i -lt 1441;$i+=1) {
          $observed.SetValue([double]$tagRows[$i].rawValue,$i+1,1)
          $observed.SetValue([string]$tagRows[$i].qualityText,$i+1,2)
          $observed.SetValue([double]$tagRows[$i].rawTime,$i+1,3)
        }
        $state=Get-CofiringMatrixResponse $observed 1441
        Assert-V7Check ($state.valueRows -eq 1441 -and $state.pendingRows -eq 0 -and $state.noDataRows -eq 0 -and $state.errorRows -eq 0) ('actual V6 complete response '+$key)
        if ($key -eq 'unit1CoalA2') { $second=$observed }
      }
      Assert-V7Check ($v6.observedCompletedTags -eq 1 -and $v6.observedActiveBatch.stableReads -eq 1 -and $v6.observedActiveBatch.response.complete) 'V6 rejected a first complete response, not missing samples'
      # Actual elapsed time is from the uploaded EnableCalculation begin to classification.
      $arrival=[double]$v6.timingEvidence.acquisitionElapsedSeconds
      $d=Get-CofiringBatchDecision $second $null 1441 0 $false -ElapsedSeconds $arrival -FirstCompleteSeconds -1
      Assert-V7Check ($d.action -eq 'WAIT' -and $d.phase -eq 'VERIFY_STABLE' -and $d.stableReads -eq 1 -and $d.deadlineSeconds -eq ($arrival+15)) 'V6 first complete response after 30 seconds now gets its separate verification window'
      $d2=Get-CofiringBatchDecision $second $second 1441 $d.stableReads $false -ElapsedSeconds ($arrival+1.5) -FirstCompleteSeconds $d.firstCompleteSeconds
      Assert-V7Check ($d2.action -eq 'WAIT' -and $d2.stableReads -eq 2 -and $d2.deadlineSeconds -eq ($arrival+15)) 'second complete snapshot does not reset deadline'
      $d3=Get-CofiringBatchDecision $second $second 1441 $d2.stableReads $false -ElapsedSeconds ($arrival+3) -FirstCompleteSeconds $d2.firstCompleteSeconds
      Assert-V7Check ($d3.action -eq 'COMPLETE' -and $d3.stableReads -eq 3) 'SIMULATED later equal reads can complete, actual V6 had only one'
      $lastMinute=Get-CofiringBatchDecision $second $null 1441 0 $false -ElapsedSeconds 59.5
      Assert-V7Check ($lastMinute.action -eq 'WAIT' -and $lastMinute.deadlineSeconds -eq 74.5) 'near acquisition cutoff still has its own bounded stability window'
      $late=Get-CofiringBatchDecision $second $null 1441 0 $false -ElapsedSeconds 60.0
      Assert-V7Check ($late.action -eq 'TIMEOUT' -and $late.firstCompleteSeconds -eq -1) 'first response at or after acquisition deadline cannot pass'
      $atDeadline=Get-CofiringBatchDecision $second $second 1441 2 $false -ElapsedSeconds 46.5 -FirstCompleteSeconds 31.5
      Assert-V7Check ($atDeadline.action -eq 'TIMEOUT') 'third identical read at stability deadline cannot pass'
      $hardExpired=Get-CofiringBatchDecision $second $second 1441 2 $true -ElapsedSeconds 34.5 -FirstCompleteSeconds 31.5
      Assert-V7Check ($hardExpired.action -eq 'TIMEOUT') 'external hard expiry always blocks success'
      $regressed=Get-CofiringBatchDecision $actual $second 1441 2 $false -ElapsedSeconds 35 -FirstCompleteSeconds 31.5
      Assert-V7Check ($regressed.action -eq 'WAIT' -and $regressed.stableReads -eq 0 -and $regressed.firstCompleteSeconds -eq 31.5 -and $regressed.deadlineSeconds -eq 46.5) 'metadata regression does not reopen acquisition or reset stability time'
      $regressedLate=Get-CofiringBatchDecision $actual $actual 1441 0 $false -ElapsedSeconds 46.5 -FirstCompleteSeconds 31.5
      Assert-V7Check ($regressedLate.action -eq 'TIMEOUT') 'regressed metadata has a fixed stop time'
      $neverReady=Get-CofiringBatchDecision $actual $actual 1441 0 $false -ElapsedSeconds 60
      Assert-V7Check ($neverReady.action -eq 'TIMEOUT' -and $neverReady.firstCompleteSeconds -eq -1) 'persistent metadata zeros are still rejected after 60 seconds'
      $changed=$second.Clone();$changed.SetValue([double]$second.GetValue(1,1)+1.0,1,1)
      $changedD=Get-CofiringBatchDecision $changed $second 1441 2 $false -ElapsedSeconds 35 -FirstCompleteSeconds 31.5
      Assert-V7Check ($changedD.action -eq 'WAIT' -and $changedD.stableReads -eq 1 -and $changedD.deadlineSeconds -eq 46.5) 'changed complete values reset count but not deadline'
      $invalidClock=$false
      try { $null=Get-CofiringBatchDecision $second $null 1441 0 $false -ElapsedSeconds 5 -FirstCompleteSeconds 10 } catch { $invalidClock=$true }
      Assert-V7Check $invalidClock 'invalid phase clock cannot authorize success'
      Assert-V7Check ($timeoutSeconds -eq 900 -and $cleanupGraceSeconds -eq 60) 'sequential ten-TAG controller budget and separate cleanup allowance'
      Assert-V7Check ($timeoutSeconds -gt (30+10*75+60)) 'whole-job budget covers bounded acquisition, stability and validation planning'


    } finally {
      $env:GS_COFIRING_COM_TRACE_PATH=$oldTrace
      $env:GS_COFIRING_CANCEL_PATH=$oldCancel
      [IO.Directory]::Delete($mockDir,$true)
    }
    [Console]::WriteLine('PASS: V7 focused helper assertions including actual V5/V6 arrays and phase deadlines: '+$script:v7Assertions+' (mocked calls; Excel not started).')

    [Console]::WriteLine('PASS: V7 날짜 경계·PowerShell 구문·NODATA 완료/유효성 분리·대기값·0값·품질·시각·COM 배열·일시적 COM 오류 재시도·영구 오류 차단·취소·종료 판정 분리·수신/안정화 시간 분리 검사. Excel은 시작하지 않았습니다.')
    exit 0
  }
  if ($env:OS -ne 'Windows_NT') { throw '이 시험은 회사 Windows PC에서 실행해 주세요.' }
  $zone=[TimeZoneInfo]::FindSystemTimeZoneById('Korea Standard Time')
  $nowKst=[TimeZoneInfo]::ConvertTime([DateTimeOffset]::Now,$zone).DateTime
  if ($daily.QueryEnd -gt $nowKst) { throw ('아직 하루가 완료되지 않았습니다. ' + $Date + ' 자료는 ' + $QueryEnd + ' (한국 시각) 이후 조회할 수 있습니다. Excel은 시작하지 않았습니다.') }


  $controllerProcess = Get-Process -Id $PID -ErrorAction Stop
  try { $controllerSignature = New-ControllerSignature $controllerProcess } finally { $controllerProcess.Dispose() }
  $expectedExcelPath = Resolve-ControllerExcelExecutable
  $controllerMutex = [Threading.Mutex]::new($false, 'Local\GSShiftLog.BlowerRuntimeDataParcHiddenExcelNativeOmV1')
  try { $controllerMutexAcquired = [bool]$controllerMutex.WaitOne(0, $false) }
  catch [Threading.AbandonedMutexException] { $controllerMutexAcquired = $true }
  if (-not $controllerMutexAcquired) { throw '다른 DataPARC 숨김 Excel 조회가 진행 중입니다. Blower 조회 완료 후 다시 실행해 주세요.' }

  foreach ($process in @(Get-Process -Name EXCEL -ErrorAction SilentlyContinue | Where-Object { [int]$_.SessionId -eq [int]$controllerSignature.SessionId })) {
    try { $baselineExcel += New-ControllerSignature $process } finally { $process.Dispose() }
  }
  foreach ($process in @(Get-Process -Name 'CTCExcelAddIn.PARCviewHost' -ErrorAction SilentlyContinue | Where-Object { [int]$_.SessionId -eq [int]$controllerSignature.SessionId })) {
    try { $baselineHosts += New-ControllerSignature $process } finally { $process.Dispose() }
  }
  if ([string]::IsNullOrWhiteSpace($OutputDirectory)) {
    $OutputDirectory = Join-Path (Join-Path $env:USERPROFILE 'Downloads') ('cofiring-dataparc-daily-v7-' + $Date + '-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '-' + $runId.Substring(0, 8))
  }
  $OutputDirectory = [IO.Path]::GetFullPath($OutputDirectory)
  [void][IO.Directory]::CreateDirectory($OutputDirectory)
  foreach ($name in @('pilot-result.json', 'pilot-report.json', 'pilot-report.txt', 'raw-diagnostics.json', 'worker-stdout.log', 'worker-stderr.log')) {
    if ([IO.File]::Exists((Join-Path $OutputDirectory $name))) { throw '출력 폴더에 기존 조회 결과가 있습니다. 다른 OutputDirectory를 지정해 주세요.' }
  }
  $outputReady = $true
  $initialDiagnostic = [ordered]@{schemaVersion=1;kind='cofiring_dataparc_raw';runId=$runId;start=$Start;end=$End;targetDate=$Date;queryStart=$Start;queryEnd=$QueryEnd;samples=@();failure='조회 worker가 아직 결과를 기록하지 않았습니다.';databaseWritten=$false;productionReady=$false}
  [IO.File]::WriteAllText((Join-Path $OutputDirectory 'raw-diagnostics.json'),($initialDiagnostic | ConvertTo-Json -Depth 6),$utf8)
  $temporaryDirectory = Join-Path ([IO.Path]::GetTempPath()) ('gs-cofiring-dataparc-' + $runId)
  [void][IO.Directory]::CreateDirectory($temporaryDirectory)
  $workerPath = Join-Path $temporaryDirectory 'cofiring-worker.ps1'
  $ownershipPath = Join-Path $temporaryDirectory 'ownership.json'
  $cancelPath=Join-Path $temporaryDirectory 'cancel.request'
  $resultPath=Join-Path $OutputDirectory 'pilot-result.json'
  $gapPath=Join-Path $OutputDirectory 'gap-probes.json'
  $stdoutPath = Join-Path $OutputDirectory 'worker-stdout.log'
  $stderrPath = Join-Path $OutputDirectory 'worker-stderr.log'
  [IO.File]::WriteAllText($workerPath, $workerText, (New-Object Text.UTF8Encoding($true)))
  $powerShellPath = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
  if (-not [IO.File]::Exists($powerShellPath)) { throw 'Windows PowerShell 5.1 실행 파일을 찾을 수 없습니다.' }
  [Console]::WriteLine('혼소율 하루 조회 V7 · ' + $Start + ' ~ ' + $QueryEnd + ' / 하루 24시간, 1441개 경계값')
  [Console]::WriteLine('TAG 하나씩 1441분 경계 조회 · 품질/시각 0은 미완료로 분리 · 최대 활성 수식 4323개 · 수신 60초 + 첫 완료 후 검증 15초/TAG · 전체 상한 900초 / 정리 대기 60초.')
  [IO.File]::WriteAllText((Join-Path $OutputDirectory 'controller-state.json'), ([ordered]@{status='RUNNING';runId=$runId;targetDate=$Date;controllerPid=$PID;startedAtUtc=[datetime]::UtcNow.ToString('o');cleanupVerified=$false;databaseWritten=$false} | ConvertTo-Json), $utf8)
  $workerEnvironment = @{
    GS_COFIRING_START = $Start
    GS_COFIRING_END = $End
    GS_COFIRING_DIAGNOSTICS_PATH = (Join-Path $OutputDirectory 'raw-diagnostics.json')
    GS_COFIRING_RUN_ID = $runId
    GS_COFIRING_CANCEL_PATH = $cancelPath
    GS_COFIRING_RESULT_PATH = $resultPath
    GS_COFIRING_GAP_PATH = $gapPath
    GS_COFIRING_COM_TRACE_PATH = (Join-Path $OutputDirectory 'com-calls.jsonl')
    GS_COFIRING_PARTIAL_PATH = (Join-Path $OutputDirectory 'partial-snapshot.json')
    GS_COFIRING_OWNERSHIP_PATH = $ownershipPath
    GS_COFIRING_CONTROLLER_SIGNATURE = ($controllerSignature | ConvertTo-Json -Compress)
  }
  $priorEnvironment = @{}
  try {
    foreach ($key in $workerEnvironment.Keys) {
      $priorEnvironment[$key] = [Environment]::GetEnvironmentVariable($key, 'Process')
      [Environment]::SetEnvironmentVariable($key, [string]$workerEnvironment[$key], 'Process')
    }
    $startedAt = [datetime]::UtcNow
    $deadline = $startedAt.AddSeconds($timeoutSeconds)
    $worker = Start-Process -FilePath $powerShellPath -ArgumentList @('-NoProfile', '-STA', '-ExecutionPolicy', 'Bypass', '-File', ('"' + $workerPath + '"')) -WindowStyle Hidden -RedirectStandardOutput $stdoutPath -RedirectStandardError $stderrPath -PassThru
    $workerSignature = New-ControllerSignature $worker
    $workerSignature | Add-Member -NotePropertyName ParentProcessId -NotePropertyValue ([int]$controllerSignature.ProcessId)
  } finally {
    foreach ($key in $priorEnvironment.Keys) { [Environment]::SetEnvironmentVariable($key, $priorEnvironment[$key], 'Process') }
  }
  while (-not $worker.HasExited) {
    $worker.Refresh()
    Show-ControllerLog $stdoutPath
    Show-ControllerLog $stderrPath
    if ([datetime]::UtcNow -ge $deadline) {
      $timedOut = $true
      throw ('전체 '+$timeoutSeconds+'초 제한시간을 초과했습니다. 조회용 프로세스를 정리합니다.')
    }
    Start-Sleep -Milliseconds 300
  }
  [void]$worker.WaitForExit(1000) # Bounded wait; never wait forever for redirected child streams.
  $workerExitCode = [int]$worker.ExitCode
} catch {
  $controllerFailure = $_.Exception.Message
  [Console]::WriteLine('[실패] ' + $controllerFailure)
} finally {
  try {
    Invoke-ControllerCleanup
    foreach ($signature in @($baselineExcel) + @($baselineHosts)) {
      if (-not (Test-ControllerSignature $signature)) {
        $cleanupErrors.Add('기존 사용자 프로세스가 조회 중 변경되거나 종료되었습니다. PID=' + [string]$signature.ProcessId)
      }
    }
    $script:processCleanupVerified=($cleanupErrors.Count -eq 0 -and $null -ne $workerSignature -and $null -ne $ownedExcel)
    if ($outputReady) {
      if ($ownershipPath -and [IO.File]::Exists($ownershipPath)) { [IO.File]::Copy($ownershipPath,(Join-Path $OutputDirectory 'ownership.json'),$true) }
      $processAfter=[ordered]@{runId=$runId;processCleanupVerified=[bool]$processCleanupVerified;errors=@($cleanupErrors.ToArray());actions=@($cleanupActions.ToArray())}
      [IO.File]::WriteAllText((Join-Path $OutputDirectory 'process-cleanup.json'),($processAfter | ConvertTo-Json -Depth 10),$utf8)
    }
    if ($stdoutPath) { Show-ControllerLog $stdoutPath -Final }
    if ($stderrPath) { Show-ControllerLog $stderrPath -Final }
    if ($worker -and $worker.HasExited) { $workerExitCode = [int]$worker.ExitCode }
  } catch { $cleanupErrors.Add('정리 관리 오류: ' + $_.Exception.Message) }
  finally {
    # The shared mutex is released only AFTER owned Excel/Host/worker cleanup.
    if ($controllerMutex) {
      if ($controllerMutexAcquired) { try { $controllerMutex.ReleaseMutex() } catch { } }
      $controllerMutex.Dispose()
    }
    if ($ownedExcelProcessPinned) { $ownedExcelProcessPinned.Dispose() }
    if ($worker) { $worker.Dispose() }
    if ($temporaryDirectory -and [IO.Directory]::Exists($temporaryDirectory)) {
      try { [IO.Directory]::Delete($temporaryDirectory, $true) }
      catch { $cleanupErrors.Add('조회 임시 폴더 제거 실패: ' + $_.Exception.Message) }
    }
    Save-ControllerReport
  }
}
if ($success) { exit 0 }
exit 1
